function review(){let wrongs=getWrongIds();const saved=state.bookmarks;let q=state.questions.filter(x=>wrongs.includes(x.id)||saved.includes(x.id));return shell(`<div class="stack"><div class="eyebrow">REPETIR • ENTENDER • SUPERAR</div><h1 class="headline">Caderno de revisão</h1><p class="muted">Questões erradas e salvas permanecem aqui até você dominá-las.</p><div class="grid g3"><div class="card stat"><div class="number">${wrongs.length}</div><div class="muted">Erros pendentes</div></div><div class="card stat"><div class="number">${saved.length}</div><div class="muted">Salvas</div></div><div class="card stat"><div class="number">${q.length}</div><div class="muted">Na revisão</div></div></div>${q.length?`<div class="card stack">${q.slice(0,10).map(x=>`<div class="mission"><div class="stack-tight"><b>${esc(x.subject)}</b><span class="muted tiny">${esc(x.topic)} · ${esc(x.id)}</span></div><button class="btn outline sm" data-action="single:${x.id}">Resolver ${ic('arrow',15)}</button></div>`).join('')}</div>${btn('Iniciar revisão de erros','start-errors','primary full')}`:`<div class="card stack"><div class="subhead">Seu caderno ainda está vazio.</div><p class="muted">Faça o primeiro treino e suas dúvidas aparecerão aqui automaticamente.</p>${btn('Começar a praticar','nav:train','primary')}</div>`}</div>`)}
function radar(){let p=progressOf(state.attempts);const angles=subj.map((_,i)=>-Math.PI/2+i*Math.PI*2/5);const coords=(vals,scale)=>vals.map((v,i)=>`${(160+Math.cos(angles[i])*112*v*scale).toFixed(1)},${(160+Math.sin(angles[i])*112*v*scale).toFixed(1)}`).join(' ');const vals=subj.map(s=>p.by[s.name].total?p.by[s.name].pct/100:0);return shell(`<div class="stack"><div class="eyebrow">INTELIGÊNCIA DE ESTUDOS</div><h1 class="headline">Seu radar de conhecimento</h1><p class="muted">Acompanhe a precisão de cada disciplina e defina sua próxima prioridade.</p>${V.radar(state.attempts,subj,state.radarRange||'30')}<div class="grid g2"><div class="card" style="text-align:center"><svg viewBox="0 0 320 320" width="100%" style="max-width:340px" role="img" aria-label="Radar de desempenho por disciplina">${[.25,.5,.75,1].map(a=>`<polygon points="${coords([a,a,a,a,a],1)}" fill="none" stroke="#466278" stroke-width="1"/>`).join('')}${angles.map(a=>`<line x1="160" y1="160" x2="${160+Math.cos(a)*112}" y2="${160+Math.sin(a)*112}" stroke="#466278"/>`).join('')}<polygon points="${coords(vals,1)}" fill="rgba(96,210,192,.22)" stroke="#6ad8ca" stroke-width="2"/>${angles.map((a,i)=>`<text x="${160+Math.cos(a)*143}" y="${164+Math.sin(a)*143}" font-size="10" fill="#bfccda" text-anchor="middle">${['Português','Direito','Matemática','Inglês','Literatura'][i]}</text>`).join('')}</svg><div class="muted tiny">Indicador de acertos, não estimativa de aprovação.</div></div><div class="card stack"><h3>Detalhamento por disciplina</h3>${subj.map(s=>{const x=p.by[s.name];return `<div class="stack-tight"><div class="row between"><span class="small">${esc(s.short)}</span><b>${x.total?x.pct+'%':'Sem dados'}</b></div><div class="progress"><div style="width:${x.pct}%"></div></div><div class="muted tiny">${x.correct} acertos de ${x.total} respostas</div></div>`}).join('')}</div></div><div class="card stack"><div class="row">${ic('chart',22)} <h3>Como usar seu radar</h3></div><p class="muted small">Estude primeiro as matérias com menor precisão, mas continue praticando todas. As taxas são baseadas nas respostas registradas, inclusive revisões; não representam sua nota prevista.</p>${btn('Treinar uma matéria','nav:train','primary')}</div></div>`)}
function admin(){if(!isAdmin())return shell('<div class="card">Acesso restrito.</div>');const people=state.people||[];const all=state.allAttempts||[];const reports=state.reports||[];return shell(`<div class="stack"><div class="eyebrow">ACESSO EXCLUSIVO DO ADMINISTRADOR</div><h1 class="headline">Central de comando</h1><p class="muted">Gerencie os estudantes, acompanhe a evolução e revise possíveis problemas do acervo.</p><div class="grid g3"><div class="card stat">${ic('users',22)}<div class="number">${people.length}</div><div class="muted">Usuários</div></div><div class="card stat">${ic('book',22)}<div class="number">${state.questions.length}</div><div class="muted">Questões no banco</div></div><div class="card stat">${ic('target',22)}<div class="number">${all.length}</div><div class="muted">Respostas registradas</div></div></div><div class="banner-info">${ic('calendar',17)} <b>${(state.officialAdminRuns||[]).length}</b> simulados oficiais registrados por estudantes.</div><div class="grid g2"><div class="card stack"><h3>Criar novo acesso</h3>${state.demo?`<div class="banner-warning">Exibição de demonstração: criação de usuários disponível apenas quando o backend seguro estiver conectado.</div>`:''}<p class="muted tiny">Somente contas criadas por você. Não existe cadastro público.</p><form id="create-user" class="stack"><div class="field"><label>Nome do estudante</label><input name="name" required minlength="2" placeholder="Nome completo"></div><div class="field"><label>E-mail de acesso</label><input name="email" type="email" required placeholder="aluno@exemplo.com"></div><div class="field"><label>Senha provisória</label><input name="password" type="password" required minlength="12" placeholder="Mínimo de 12 caracteres"></div><button class="btn primary full" type="submit" ${state.demo?'disabled':''}>${ic('users',17)} Criar usuário</button></form><div class="banner-info">Use a função segura do Supabase para criar contas. A senha nunca será enviada para o GitHub.</div></div><div class="card stack"><h3>Meta editorial · 500 por disciplina</h3><p class="muted small">A meta de cadastro de 2.500 questões foi alcançada. A revisão pedagógica continua. Só contabilizamos no banco principal itens inseridos; provas completas ficam na aba de Simulados. Questões de concurso exigem identificação de prova e gabarito final.</p>${subj.map(item=>{const total=state.questions.filter(q=>q.subject===item.name).length;const real=state.questions.filter(q=>q.subject===item.name&&q.origin==='real').length;return `<div class="stack-tight"><div class="row between"><b class="small">${esc(item.short)}</b><span class="muted tiny">${total}/500 · ${real} reais</span></div><div class="progress"><div style="width:${Math.min(100,total/5)}%"></div></div></div>`}).join('')}<h3>Qualidade do conteúdo</h3><p class="muted small">Questões autorais continuam em revisão pedagógica. A origem das questões reais exige documento, ano, cargo e número; relatos de gabarito são monitorados nesta área.</p><div class="row between"><span>Relatos recebidos</span><b>${reports.length}</b></div>${reports.length?reports.slice(0,8).map(r=>`<div class="subject-card stack-tight" style="display:block"><b>${esc(r.question_id)}</b><div class="muted small">${esc(r.details)}</div><div class="tiny gold">${esc(r.status||'aberto')}</div></div>`).join(''):'<div class="muted small">Nenhum relato recebido até agora.</div>'}</div></div><div class="card stack"><h3>Progresso por usuário</h3><div class="table-wrap"><table class="table"><thead><tr><th>Estudante</th><th>Respostas</th><th>Acertos</th><th>Precisão</th><th>XP</th><th>Último treino</th><th>Simulados</th><th>Detalhes</th><th>Conta</th></tr></thead><tbody>${people.map(p=>{let as=all.filter(a=>a.user_id===p.user_id),x=progressOf(as);let last=as.length?fmtDate(as[0].created_at):'—';return `<tr><td><b>${esc(p.display_name||'Sem nome')}</b><div class="tiny muted">${esc(p.email||'')}</div></td><td>${x.total}</td><td>${x.correct}</td><td>${x.rate}%</td><td>${x.xp}</td><td>${last}</td><td>${(state.officialAdminRuns||[]).filter(r=>r.user_id===p.user_id).length}</td><td><button class="btn outline sm" data-action="detail:${p.user_id}">Ver radar</button></td><td><button class="btn outline sm" data-action="${p.disabled?'enable':'disable'}:${p.user_id}" ${state.demo||p.user_id===state.user.id?'disabled':''}>${p.disabled?'Reativar':'Desativar'}</button></td></tr>`}).join('')}</tbody></table></div>${state.adminDetail?(()=>{const selected=people.find(x=>x.user_id===state.adminDetail);if(!selected)return '';const ps=progressOf(all.filter(a=>a.user_id===selected.user_id));return `<div class="card stack" style="margin-top:10px"><div class="row between"><h3>Radar individual: ${esc(selected.display_name||'Estudante')}</h3><button class="btn outline sm" data-action="detail:clear">Fechar</button></div><div class="grid g3"><div><b>${ps.total}</b><div class="tiny muted">Respostas</div></div><div><b>${ps.rate}%</b><div class="tiny muted">Precisão</div></div><div><b>${ps.xp} XP</b><div class="tiny muted">Pontuação</div></div></div>${subj.map(item=>{const v=ps.by[item.name];return `<div class="stack-tight"><div class="row between"><span>${esc(item.name)}</span><b>${v.pct}% · ${v.total} respostas</b></div><div class="progress"><div style="width:${v.pct}%"></div></div></div>`}).join('')}</div>`})():''}<p class="muted tiny">Ranking e progresso são privados à administração. Os usuários não veem dados uns dos outros.</p></div></div>`)}
function achievementScreen(){return shell(V.achievementPage(state.attempts,subj))}
function loginPage(){return `<div class="auth-screen"><div class="auth-wrap enter"><div class="auth-art"><div class="logo"><span class="brandmark">${ic('shield',25)}</span><div><div class="brand">FOCO <b>PMMG</b> 2027</div><span class="micro">Disciplina · Constância · Aprovação</span></div></div><div><div class="eyebrow">Sua preparação começa aqui</div><h1>O futuro exige <span>foco.</span></h1><p>Seu espaço de treino, revisão e evolução. Uma questão por vez, um passo mais perto da farda.</p></div><div class="row wrap"><span class="pill">${ic('target',15)} Radar de desempenho</span><span class="pill">${ic('award',15)} XP e missões</span></div></div><div class="auth-panel"><div class="stack-tight"><div class="eyebrow">Acesso exclusivo</div><h2>Bem-vindo de volta.</h2><p class="muted">Entre com as credenciais fornecidas pelo administrador.</p></div>${!configured?`<div class="banner-warning">O acesso real ainda depende de configurar o Supabase exclusivo deste aplicativo. Você pode explorar a prévia local abaixo.</div>`:''}<form id="login-form" class="stack"><div class="field"><label>E-mail</label><input type="email" name="email" autocomplete="username" placeholder="seuemail@exemplo.com" required ${configured?'':'disabled'}></div><div class="field"><label>Senha</label><input type="password" name="password" autocomplete="current-password" placeholder="Sua senha" required ${configured?'':'disabled'}></div><label class="check"><input type="checkbox" name="remember" checked> Manter conectado neste dispositivo</label><button class="btn primary full" type="submit" ${configured?'':'disabled'}>Entrar no Foco PMMG ${ic('arrow',18)}</button></form><button class="btn ghost full" data-action="preview">Explorar demonstração sem conta ${ic('arrow',18)}</button><div class="muted tiny" style="text-align:center">A demonstração é local e não permite criar usuários nem acessar dados reais.</div><p class="muted tiny" style="text-align:center">Sem cadastro público · Dados individuais protegidos · Aplicação não oficial da PMMG</p></div></div></div>`}
// PROVAS ORIGINAIS: visualização do caderno de prova por PDF de terceiro + uma resposta por número.
// Não republicar os enunciados; gabarito oficial separado e anulações preservadas.
const officialDraftKey=()=>`foco_oficial_draft_${state.demo?'demo':state.user?.id||'anon'}`;
function examById(id){return officialExams.find(x=>x.id===id)}
function fmtExamTime(milliseconds){const secs=Math.max(0,Math.floor(milliseconds/1000));return `${String(Math.floor(secs/3600)).padStart(2,'0')}:${String(Math.floor(secs%3600/60)).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`}
function officialNumbers(mode,exam){return Array.from({length:exam?.answers?.length||50},(_,i)=>i+1).filter(n=>mode!=='sem_literatura'||!exam?.hasLiterature||n<21||n>25)}
function officialSubject(n,exam){if(exam?.edition===2022)return n<=10?'Português':n<=22?'Direito Penal / Constitucional':n<=28?'Direito Penal Militar':n<=32?'Direitos Humanos':n<=36?'Legislação Extravagante':'Estatística';return n<=20?'Português':n<=25?'Literatura':n<=30?'Inglês':n<=40?'Direito e Direitos Humanos':'Raciocínio Lógico-Matemático'}
function officialGrade(exam,mode,selected){const nums=officialNumbers(mode,exam);let correct=0,wrong=0,blanks=0,annulled=0;for(const n of nums){let expected=exam.answers[n-1],got=selected[String(n)]||'';if(expected===null)annulled++;else if(!got)blanks++;else if(got===expected)correct++;else wrong++}return {total:nums.length,correct,wrong,blanks,annulled,percent:Math.round(correct/(nums.length-annulled)*10000)/100}}
function officialExamHome(){const draft=localStorage.getItem(officialDraftKey());let previous=null;try{previous=JSON.parse(draft)}catch{};return shell(`<div class="stack"><div><div class="eyebrow">COLEÇÃO DE PROVAS REAIS</div><h1 class="headline" style="margin:10px 0">Simulados oficiais</h1><p class="muted">Resolva provas reais de Soldado da PMMG, com 40 ou 50 itens numerados, tempo de referência de 3 horas e correção pelo gabarito definitivo.</p></div><div class="banner-info">${ic('book',17)} O enunciado original aparece no caderno oficial incorporado abaixo do cartão de respostas. No celular, você também pode abrir o PDF em outra aba. Questões anuladas não entram no cálculo do percentual.</div>${previous&&examById(previous.id)?`<div class="card stack"><div class="eyebrow">VOCÊ TEM UM SIMULADO EM ANDAMENTO</div><h3>${esc(examById(previous.id).title)} · ${officialNumbers(previous.mode,examById(previous.id)).length} itens</h3><p class="muted small">Suas respostas estão salvas neste dispositivo.</p>${btn('Continuar de onde parei '+ic('arrow',17),'sim-resume','primary full')}</div>`:''}<div class="official-grid">${officialExams.map(e=>`<div class="card official-exam-card stack"><div class="row between"><span class="tag gold-tag">PROVA REAL · ${e.applicationYear}</span>${ic('award',24)}</div><h2>${esc(e.title)}</h2><p class="muted small">${esc(e.notice)} · ${e.answers.length} questões · 3 horas</p><div class="row wrap"><span class="pill">${ic('book',15)} Gabarito definitivo</span><span class="pill">${e.answers.filter(x=>x===null).length} anuladas</span></div>${e.hasLiterature?`<div class="banner-warning">A prova histórica inclui cinco questões de Literatura sobre os livros daquele edital. Se preferir, você pode pulá-las por enquanto.</div>`:`<div class="banner-info">Prova histórica de 40 questões, com disciplinas diferentes da edição de 2025. Use para treinar conteúdos compatíveis com o edital atual.</div>`}<div class="stack">${btn('Simulado completo · '+e.answers.length+' questões','sim-start:'+e.id+':integral','primary full')}${e.hasLiterature?btn('Sem Literatura antiga · 45 questões','sim-start:'+e.id+':sem_literatura','outline full'):''}</div><div class="row between wrap"><a class="exam-link" href="${esc(e.pdf)}" target="_blank" rel="noopener noreferrer">Caderno original ${ic('arrow',13)}</a><a class="exam-link" href="${esc(e.answerSource)}" target="_blank" rel="noopener noreferrer">Gabarito oficial ${ic('arrow',13)}</a></div></div>`).join('')}</div><div class="card stack"><h3>Seu histórico de simulados</h3>${officialRuns.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Prova</th><th>Data</th><th>Acertos</th><th>Percentual</th><th>Detalhes</th></tr></thead><tbody>${officialRuns.slice(0,12).map((r,i)=>`<tr><td>${esc(examById(r.exam_id)?.title||r.exam_id)} <span class="tiny muted">${r.mode==='sem_literatura'?'sem Literatura':'completo'}</span></td><td>${fmtDate(r.created_at)}</td><td>${r.correct}/${r.total-r.annulled}</td><td>${Number(r.percent).toFixed(1)}%</td><td><button class="btn outline sm" data-action="sim-history:${i}">Revisar</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="muted small">Seu primeiro simulado aparecerá aqui depois de concluído.</p>'}</div><div class="banner-info">O conteúdo deste módulo é histórico. Quando sair o edital do CFSd 2027, atualizaremos as obras e a estrutura da prova conforme o documento oficial.</div></div>`)}
function officialExamQuestion(){const s=officialSession;if(!s)return officialExamHome();const e=examById(s.id);if(!e)return officialExamHome();const n=s.numbers[s.index],selected=s.selected[String(n)]||'',answered=s.numbers.filter(x=>s.selected[String(x)]).length;return shell(`<div class="stack"><div class="row between wrap"><button class="btn outline sm" data-action="sim-back">${ic('back',15)} Voltar aos simulados</button><span class="pill">${ic('clock',16)} <span id="sim-clock">${fmtExamTime(Date.now()-s.started)}</span></span></div><div class="progress"><div style="width:${Math.round((s.index+1)/s.numbers.length*100)}%"></div></div><div class="row between wrap"><div class="stack-tight"><div class="eyebrow">${esc(e.label)} · Aplicação ${e.applicationYear} · ${esc(e.notice)}</div><h1 class="subhead">Questão oficial nº ${n} <span class="muted">· ${s.index+1} de ${s.numbers.length}</span></h1><p class="muted small">${esc(officialSubject(n,e))} · ${answered}/${s.numbers.length} respostas marcadas</p></div>${e.answers[n-1]===null?badge('Anulada no gabarito final','gold-tag'):badge('Sem correção antecipada')}</div><div class="official-workspace"><div class="card stack official-paper"><div class="row between wrap"><h3>Caderno oficial da PMMG</h3><a class="exam-link" target="_blank" rel="noopener noreferrer" href="${esc(e.pdf)}">Abrir PDF completo ${ic('arrow',14)}</a></div><p class="tiny muted">Procure a questão nº ${n} no PDF abaixo. O documento original mantém textos, tabelas e figuras da prova. A visualização pode depender do navegador.</p><div id="official-pdf-slot"></div><a class="exam-link" target="_blank" rel="noopener noreferrer" href="${esc(e.pdf)}">Se o PDF não carregar, abra o caderno original</a></div><div class="card stack official-answer"><div class="eyebrow">CARTÃO DE RESPOSTAS · Nº ${n}</div><h3>Marque sua alternativa</h3>${['A','B','C','D'].map(ch=>`<button class="optioncard ${selected===ch?'chosen':''}" data-action="sim-answer:${ch}" aria-pressed="${selected===ch}"><span class="letter">${ch}</span><b>Alternativa ${ch}</b>${selected===ch?ic('check',19):''}</button>`).join('')}<button class="btn outline full sm" data-action="sim-clear">Deixar em branco</button><div class="row between wrap"><button class="btn outline sm" data-action="sim-prev" ${s.index===0?'disabled':''}>${ic('back',16)} Anterior</button><button class="btn primary sm" data-action="sim-next" ${s.index===s.numbers.length-1?'disabled':''}>Próxima ${ic('arrow',16)}</button></div><div><p class="muted tiny">Ir diretamente à questão:</p><div class="official-nav-grid">${s.numbers.map((i,pos)=>`<button data-action="sim-jump:${pos}" class="official-nav-number ${pos===s.index?'current':''} ${s.selected[String(i)]?'answered':''}" title="Questão ${i}">${i}</button>`).join('')}</div></div><button class="btn primary full" data-action="sim-finish">${ic('check',17)} Finalizar e corrigir prova</button><p class="tiny muted">Você pode sair e continuar depois. Suas respostas ficam salvas até a finalização.</p></div></div></div>`)}
function officialExamResult(){const d=officialResultData;if(!d)return officialExamHome();const e=examById(d.exam_id);if(!e)return officialExamHome();const nums=officialNumbers(d.mode,e);let selected=d.selected||{};return shell(`<div class="stack official-results"><div class="card stack"><div class="row between wrap"><span class="tag gold-tag">SIMULADO CONCLUÍDO</span>${ic('award',32)}</div><div class="eyebrow">${esc(e.title)}</div><h1 class="headline">${Number(d.percent).toFixed(1)}% de acertos</h1><p class="muted">${d.mode==='sem_literatura'?'Versão reduzida sem as cinco questões das obras antigas.':e.hasLiterature?'Versão integral, com as cinco questões de Literatura.':'Versão integral de 40 questões, da grade histórica da época.'} Questões anuladas foram desconsideradas no percentual.</p><div class="grid g3"><div class="card stat"><div class="number">${d.correct}</div><div class="muted">Acertos</div></div><div class="card stat"><div class="number">${d.wrong}</div><div class="muted">Erros</div></div><div class="card stat"><div class="number">${d.blanks}</div><div class="muted">Em branco</div></div></div><div class="muted small">${d.annulled} anuladas · ${d.total} itens apresentados · ${d.total-d.annulled} válidos. ${d.id?'Resultado sincronizado.':'Demonstração: resultado salvo apenas neste navegador.'}</div></div><div class="card stack"><h3>Revisão do seu cartão de respostas</h3><div class="official-review-grid">${nums.map(n=>{let correct=e.answers[n-1],answer=selected[String(n)]||'',status=correct===null?'annulled':!answer?'blank':answer===correct?'right':'wrong';return `<div class="official-review-item ${status}"><b>Q${n}</b><small>${answer||'—'} ${correct===null?'Anulada':correct?'→ '+correct:''}</small></div>`}).join('')}</div><p class="muted tiny">✓ Acerto · ✕ Erro · — Em branco · Anulada conforme gabarito definitivo.</p><div class="row wrap"><a href="${esc(e.pdf)}" target="_blank" rel="noopener noreferrer" class="btn outline">Caderno original ${ic('arrow',16)}</a><a href="${esc(e.answerSource)}" target="_blank" rel="noopener noreferrer" class="btn outline">Gabarito final ${ic('arrow',16)}</a></div><div class="banner-info">${esc(e.note)}</div></div>${btn(ic('calendar',18)+' Outros simulados','sim-back','primary full')}</div>`)}
function saveOfficialDraft(){if(officialSession)localStorage.setItem(officialDraftKey(),JSON.stringify(officialSession))}
async function officialAction(action){
if(action==='sim-back'){officialSession=null;state.screen='simulados';render();return}
if(action.startsWith('sim-history:')){const d=officialRuns[Number(action.slice(12))];if(!d)return;officialResultData=d;state.screen='officialResult';render();return}
if(action==='sim-resume'){let s;try{s=JSON.parse(localStorage.getItem(officialDraftKey())||'null')}catch{};if(!s||!examById(s.id)||!['integral','sem_literatura'].includes(s.mode))throw Error('Não foi possível recuperar esse simulado');officialSession=s;officialSession.numbers=officialNumbers(s.mode,examById(s.id));state.screen='officialQuestion';render();return}
if(action.startsWith('sim-start:')){const parts=action.split(':');const ex=examById(parts[1]),mode=parts[2];if(!ex||!['integral','sem_literatura'].includes(mode)||(mode==='sem_literatura'&&!ex.hasLiterature))return;if(localStorage.getItem(officialDraftKey())&&!window.confirm('Começar outro simulado? O treino anterior em andamento será substituído.'))return;officialSession={id:ex.id,mode,index:0,started:Date.now(),selected:{},numbers:officialNumbers(mode,ex)};saveOfficialDraft();state.screen='officialQuestion';render();return}
const s=officialSession;if(!s)return;const q=s.numbers[s.index];
if(action.startsWith('sim-answer:')){s.selected[String(q)]=action.slice(11);saveOfficialDraft();render();return}
if(action==='sim-clear'){delete s.selected[String(q)];saveOfficialDraft();render();return}
if(action==='sim-prev'&&s.index>0){s.index--;saveOfficialDraft();render();return}
if(action==='sim-next'&&s.index<s.numbers.length-1){s.index++;saveOfficialDraft();render();return}
if(action.startsWith('sim-jump:')){const p=Number(action.slice(9));if(Number.isInteger(p)&&p>=0&&p<s.numbers.length){s.index=p;saveOfficialDraft();render()}return}
if(action==='sim-finish'){
const answered=s.numbers.filter(n=>s.selected[String(n)]).length;const missing=s.numbers.length-answered;
if(!window.confirm(`Finalizar e corrigir ${examById(s.id).title}? ${missing} questões estão em branco. Essa tentativa será registrada.`))return;
const e=examById(s.id);let data;
if(state.demo){data={...officialGrade(e,s.mode,s.selected),exam_id:s.id,mode:s.mode,selected:{...s.selected},created_at:new Date().toISOString(),user_id:'demo'};officialRuns.unshift(data);localStorage.setItem('foco_simulados_demo_results',JSON.stringify(officialRuns));}
else {const result=await req('/rest/v1/rpc/finish_official_exam',{method:'POST',body:JSON.stringify({p_exam_id:s.id,p_mode:s.mode,p_selected:s.selected})});data={...result,exam_id:s.id,mode:s.mode,selected:{...s.selected},created_at:new Date().toISOString(),user_id:state.user.id};officialRuns.unshift(data);if(isAdmin())await loadAdminData()}
officialResultData=data;officialSession=null;localStorage.removeItem(officialDraftKey());state.screen='officialResult';render();return;
}}

function welcome(){return shell(`<div class="train-layout"><div class="card stack" style="padding:35px"><div class="micro">Primeiro acesso</div><h1 class="headline">Como você prefere ser chamado?</h1><p class="muted">Vamos personalizar a sua experiência e suas mensagens diárias.</p><form id="welcome-form" class="stack"><div class="field"><label>Seu nome ou apelido</label><input name="name" maxlength="60" minlength="2" required placeholder="Como devo te chamar?"></div><button class="btn primary full" type="submit">Começar minha preparação ${ic('arrow',17)}</button></form></div></div>`)}
function render(){clearInterval(timer);const map={home,plan:planPage,train,question,result,subjects,catalog:topicsCatalog,simulados:officialExamHome,officialQuestion:officialExamQuestion,officialResult:officialExamResult,review,stats:radar,achievements:achievementScreen,admin,welcome};const currentPaper=app.querySelector('#official-pdf');if(currentPaper)currentPaper.remove();app.innerHTML=state.screen==='login'?loginPage():(map[state.screen]||home)();if(state.screen==='officialQuestion'&&officialSession){const target=app.querySelector('#official-pdf-slot');if(target){let iframe=currentPaper?.dataset.exam===officialSession.id?currentPaper:null;if(!iframe){const paper=officialExams.find(x=>x.id===officialSession.id);iframe=document.createElement('iframe');iframe.id='official-pdf';iframe.dataset.exam=paper.id;iframe.title='Caderno original de questões da PMMG';iframe.loading='lazy';iframe.src=paper.pdf+'#page='+paper.pdfFirstQuestionPage;}target.appendChild(iframe);}}if(state.screen==='officialQuestion'){timer=setInterval(()=>{const el=qs('#sim-clock');if(el&&officialSession)el.textContent=fmtExamTime(Date.now()-officialSession.started)},1000)}if(state.screen==='question'&&state.training?.focus){const tick=()=>{const el=qs('#v2-focus-clock'),t=state.training;if(!el||!t)return;const remain=Math.max(0,300-Math.floor((Date.now()-t.started)/1000));el.textContent=String(Math.floor(remain/60)).padStart(2,'0')+':'+String(remain%60).padStart(2,'0');if(remain===0&&!t.focusExpired){t.focusExpired=true;toast('Cinco minutos concluídos! Você pode terminar a questão no seu ritmo.')}};tick();timer=setInterval(tick,1000)}document.title=`Foco PMMG 2027 · ${state.screen==='login'?'Entrar':'Minha preparação'}`;bindForms();V.animate(app)}
function bindForms(){const lf=qs('#login-form');if(lf)lf.onsubmit=async(e)=>{e.preventDefault();const fd=new FormData(lf);const b=lf.querySelector('[type=submit]');b.disabled=true;b.textContent='Entrando...';try{await login(String(fd.get('email')).trim(),String(fd.get('password')),Boolean(fd.get('remember')))}catch(err){toast('Não foi possível entrar: '+err.message);b.disabled=false;b.textContent='Entrar no Foco PMMG'}};const wf=qs('#welcome-form');if(wf)wf.onsubmit=async e=>{e.preventDefault();try{await saveName(new FormData(wf).get('name'))}catch(err){toast(err.message)}};const pf=qs('#plan-settings-form');if(pf)pf.onsubmit=async e=>{e.preventDefault();await savePlanFromForm(pf)};const af=qs('#create-user');if(af)af.onsubmit=async e=>{e.preventDefault();if(!isAdmin()||state.demo)return;const fd=new FormData(af);const obj={action:'create',name:String(fd.get('name')),email:String(fd.get('email')),password:String(fd.get('password'))};const button=af.querySelector('[type=submit]');button.disabled=true;try{await adminAction(obj);await loadAdminData();render();toast('Usuário criado com sucesso. Envie as credenciais em canal seguro.')}catch(err){toast('Não foi possível criar: '+err.message);button.disabled=false}}}
async function adminAction(obj){if(state.demo)throw Error('Indisponível na prévia');const response=await req(`/functions/v1/${C.functionName||'manage-users'}`,{method:'POST',body:JSON.stringify(obj)});return response}
async function dispatch(action){if(!action)return;try{if(action.startsWith('plan:')){await planAction(action);return;}if(action.startsWith('catalog:')){state.catalogSubject=decodeURIComponent(action.slice(8));switchScreen('catalog');return;}if(action.startsWith('catalog-area:')){const area=decodeURIComponent(action.slice(13));selection={total:10,subject:state.catalogSubject,area,topic:null,mode:'novas'};begin();return;}if(action.startsWith('catalog-topic:')){const topic=decodeURIComponent(action.slice(14));selection={total:10,subject:state.catalogSubject,area:null,topic,mode:'novas'};begin();return;}if(action.startsWith('sim-')){await officialAction(action);return;}if(action.startsWith('radar-range:')){state.radarRange=action.slice(12);render();return}if(action==='focus5'){selection={total:5,mode:'inteligente',subject:'Todas as matérias',area:null,topic:null};begin(true);return}if(action==='logout'){logout();return}if(action.startsWith('detail:')){if(!isAdmin())return;state.adminDetail=action.slice(7)==='clear'?null:action.slice(7);render();return}if(action==='preview'){await startDemo();return}if(action.startsWith('nav:')){switchScreen(action.slice(4));return}if(action.startsWith('total:')){selection={...selection,total:Number(action.split(':')[1])};render();return}if(action.startsWith('subject:')){selection={...selection,subject:action.slice(8),area:null,topic:null};render();return}if(action.startsWith('mode:')){selection={...selection,mode:action.slice(5)};render();return}if(action==='filter-clear'){selection={total:10,mode:'inteligente',subject:'Todas as matérias',area:null,topic:null};render();return}if(action==='begin'){begin();return}if(action.startsWith('practice:')){selection={total:10,mode:'inteligente',subject:action.slice(9),area:null,topic:null};begin();return}if(action==='start-errors'){selection={total:10,subject:'Todas as matérias',mode:'erros'};begin();return}if(action.startsWith('single:')){const q=state.questions.find(x=>x.id===action.slice(7));if(q){state.training={queue:[q],index:0,selected:null,confirmed:false,correct:0,earned:0,started:Date.now(),questionStarted:Date.now(),clientId:crypto.randomUUID(),answers:[],subject:q.subject,mode:'revisao',focus:false,saved:false};state.screen='question';render()}return}if(action.startsWith('answer:')){if(state.training&&!state.training.confirmed){state.training.selected=Number(action.slice(7));render()}return}if(action==='confirm'){await confirm();return}if(action==='next'){await next();return}if(action==='end'){await completeTraining();state.screen='result';render();return}if(action.startsWith('bookmark:')){const id=action.slice(9),exists=state.bookmarks.includes(id);if(state.demo){state.bookmarks=exists?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];localStorage.setItem('foco_demo_bookmarks',JSON.stringify(state.bookmarks))}else{if(exists){await req(`/rest/v1/bookmarks?question_id=eq.${encodeURIComponent(id)}`,{method:'DELETE'});state.bookmarks=state.bookmarks.filter(x=>x!==id)}else{await req('/rest/v1/bookmarks',{method:'POST',body:JSON.stringify({user_id:state.user.id,question_id:id})});state.bookmarks.push(id)}}render();return}if(action.startsWith('report:')){const id=action.slice(7),detail=prompt('Descreva o problema encontrado nesta questão (sem dados pessoais):');if(!detail?.trim())return;if(state.demo){toast('Relatos só podem ser enviados com login real.')}else{await req('/rest/v1/reports',{method:'POST',body:JSON.stringify({question_id:id,user_id:state.user.id,details:detail.trim().slice(0,800)})});toast('Relato enviado para a administração.')}return}if(action.startsWith('disable:')||action.startsWith('enable:')){if(!isAdmin())return;const [verb,id]=action.split(':');if(!window.confirm(verb==='disable'?'Deseja desativar este acesso?':'Deseja reativar este acesso?'))return;await adminAction({action:verb,id});await loadAdminData();render();toast('Acesso atualizado.');return}}catch(err){console.error(err);toast('Ocorreu um problema: '+err.message)}}
document.addEventListener('input',e=>{if(e.target?.id!=='topic-search')return;const query=T.norm(e.target.value);for(const section of document.querySelectorAll('.topic-area')){let matches=0;for(const row of section.querySelectorAll('.topic-row')){const show=!query||T.norm(row.dataset.search).includes(query);row.hidden=!show;if(show)matches++;}const areaHit=T.norm(section.dataset.area).includes(query);section.hidden=Boolean(query)&&!areaHit&&!matches;if(query&&(areaHit||matches))section.open=true;}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();dispatch(b.getAttribute('data-action'))}});
async function bootstrap(){try{const stored=localStorage.getItem(storeKey)||sessionStorage.getItem(storeKey);if(configured&&stored){state.session=JSON.parse(stored);state.user=state.session.user;state.remember=state.session.remember;if((state.session.expires_at||0)<Math.floor(Date.now()/1000)+60)await refreshSession();await loadProfileAndData();state.screen=state.profile?.onboarded?'home':'welcome'}}catch(err){console.warn('Não foi possível restaurar sessão',err);localStorage.removeItem(storeKey);sessionStorage.removeItem(storeKey);state.screen='login'}render();if('serviceWorker'in navigator&&!location.protocol.startsWith('file'))navigator.serviceWorker.register('./sw.js').catch(()=>{})}
bootstrap();